// Throwaway: cost of one Children() read and of a one-pass descendant walk, idle machine state.
package main

import (
	"context"
	"fmt"
	"os"
	"sort"
	"time"

	"github.com/shirou/gopsutil/v4/process"
)

func pct(d []time.Duration, p int) time.Duration {
	sort.Slice(d, func(i, j int) bool { return d[i] < d[j] })
	return d[len(d)*p/100]
}

func main() {
	pids, _ := process.Pids()
	me, _ := process.NewProcess(int32(os.Getpid()))
	var one, pass []time.Duration
	for i := 0; i < 30; i++ {
		s := time.Now()
		_, _ = me.Children()
		one = append(one, time.Since(s))
	}
	// one pass: list every process once, read ppid once, build the tree in memory.
	for i := 0; i < 30; i++ {
		s := time.Now()
		ps, _ := process.ProcessesWithContext(context.Background())
		kids := map[int32][]int32{}
		for _, p := range ps {
			if pp, err := p.Ppid(); err == nil {
				kids[pp] = append(kids[pp], p.Pid)
			}
		}
		_ = kids
		pass = append(pass, time.Since(s))
	}
	fmt.Printf("processes (process.Pids): %d\n", len(pids))
	fmt.Printf("one Children() read: median %v p95 %v max %v (30 reads)\n", pct(one, 50), pct(one, 95), one[len(one)-1])
	fmt.Printf("one-pass table (Processes + Ppid): median %v p95 %v max %v (30 reads)\n", pct(pass, 50), pct(pass, 95), pass[len(pass)-1])
}
EOF
